1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/** Insurance values are independent of base premiums and of any premium modifier. */
68	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	
77	const DEDUCTIBLE_PER_DAMAGE = 100;
78	const CAP_MULTIPLIER = 2;
79	
80	const COMPONENT_TYPES = ["rune", "moonstone"];
81	const BLOCK_SIZE = 3;
82	const BLOCK_BASE_PREMIUM = 60;
83	const CURSE_SURCHARGE_RATE = 0.5;
84	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
85	const HIGH_ENCHANTMENT_THRESHOLD = 5;
86	const LOYALTY_DISCOUNT_RATE = 0.2;
87	const LOYALTY_YEARS_THRESHOLD = 2;
88	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
89	
90	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
91	
92	/** Premiums round up — in the MHPCO's favour. */
93	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
94	
95	/** Payouts round down — also in the MHPCO's favour. */
96	const roundDownToWholeG = (amount: number): number => Math.floor(amount);
97	
98	const groupByType = (items: Item[]): Map<string, Item[]> => {
99	  const groups = new Map<string, Item[]>();
100	  for (const item of items) {
101	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
102	  }
103	  return groups;
104	};
105	
106	const basePremiumForItem = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
107	
108	/**
109	 * Components are priced per group of alike items, because a building block of
110	 * exactly 3 alike components earns a special rate. Main items price per item.
111	 */
112	const basePremiumForGroup = (type: string, group: Item[]): number => {
113	  if (COMPONENT_TYPES.includes(type) && group.length === BLOCK_SIZE) {
114	    return BLOCK_BASE_PREMIUM;
115	  }
116	  return sum(group.map(basePremiumForItem));
117	};
118	
119	/** Item-specific surcharges apply to the affected item's own base premium. */
120	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
121	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
122	  {
123	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
124	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
125	  },
126	];
127	
128	const itemSurchargeTotalFor = (item: Item): number =>
129	  sum(
130	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
131	      ({ rate }) => basePremiumForItem(item) * rate,
132	    ),
133	  );
134	
135	/**
136	 * Policy-wide modifiers are rates on the UNMODIFIED policy base premium — not
137	 * on the running total, and not on the item surcharges. Charging 10 % of a
138	 * cursed sword's 150 G rather than of its 100 G base is the mistake this
139	 * indirection exists to prevent.
140	 */
141	const policyModifierTotalFor = (policyBasePremium: number, rates: number[]): number =>
142	  sum(rates.map((rate) => policyBasePremium * rate));
143	
144	/**
145	 * Discounts are negative rates, so the policy modifiers stay a single sum.
146	 *
147	 * The initial assessment surcharge is deliberately NOT in here: it is charged on
148	 * every policy, including a long-standing customer's follow-up contract, so it
149	 * depends on nothing about the customer.
150	 */
151	const customerModifierRatesFor = (customer: Customer): number[] =>
152	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? [-LOYALTY_DISCOUNT_RATE] : [];
153	
154	/** The follow-up discount depends on scenario position, not on the customer. */
155	const policyModifierRatesFor = (customer: Customer, isFollowUpContract: boolean): number[] => [
156	  INITIAL_ASSESSMENT_SURCHARGE_RATE,
157	  ...customerModifierRatesFor(customer),
158	  ...(isFollowUpContract ? [-FOLLOW_UP_DISCOUNT_RATE] : []),
159	];
160	
161	/**
162	 * The customer and the contract's position in the scenario are context, not
163	 * subject: they are named at the call site so a bare `true` never has to be
164	 * decoded back into "this is a follow-up contract".
165	 */
166	interface PolicyContext {
167	  customer: Customer;
168	  isFollowUpContract: boolean;
169	}
170	
171	const quotePremium = (items: Item[], { customer, isFollowUpContract }: PolicyContext): number => {
172	  const policyBasePremium = sum(
173	    [...groupByType(items)].map(([type, group]) => basePremiumForGroup(type, group)),
174	  );
175	  const itemSurchargeTotal = sum(items.map(itemSurchargeTotalFor));
176	  const policyModifierTotal = policyModifierTotalFor(
177	    policyBasePremium,
178	    policyModifierRatesFor(customer, isFollowUpContract),
179	  );
180	  return roundUpToWholeG(
181	    policyBasePremium + itemSurchargeTotal + policyModifierTotal + PROCESSING_FEE,
182	  );
183	};
184	
185	/** A policy created by a quote step; claims draw down its remaining cap. */
186	interface Policy {
187	  items: Item[];
188	  remainingCap: number;
189	}
190	
191	const openPolicy = (items: Item[]): Policy => {
192	  const insuranceSum = sum(items.map((item) => INSURANCE_VALUE_BY_TYPE[item.type]));
193	  return { items, remainingCap: insuranceSum * CAP_MULTIPLIER };
194	};
195	
196	/** Each damage entry carries its own deductible. */
197	const reimbursementFor = (damage: Damage): number =>
198	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
199	
200	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
201	  const claimed = sum(incident.damages.map(reimbursementFor));
202	  const payout = roundDownToWholeG(Math.min(claimed, policy.remainingCap));
203	  policy.remainingCap -= payout;
204	  return { payout, remainingCap: policy.remainingCap };
205	};
206	
207	export const runScenario = (scenario: Scenario): ScenarioResult => {
208	  const results: StepResult[] = [];
209	  /** Keyed by step index, because that is what a claim's `policy` refers to. */
210	  const policiesByStepIndex = new Map<number, Policy>();
211	  let quotesSoFar = 0;
212	
213	  scenario.steps.forEach((step, stepIndex) => {
214	    if (step.op === "quote") {
215	      results.push({
216	        premium: quotePremium(step.items, {
217	          customer: scenario.customer,
218	          isFollowUpContract: quotesSoFar > 0,
219	        }),
220	      });
221	      quotesSoFar += 1;
222	      policiesByStepIndex.set(stepIndex, openPolicy(step.items));
223	      return;
224	    }
225	
226	    const policy = policiesByStepIndex.get(step.policy)!;
227	    results.push(settleClaim(policy, step.incident));
228	  });
229	
230	  return { results };
231	};
